head.script:
// ������ webRTC 다대다 화상통화 구현
const ICE_SERVERS = [
    { urls: 'stun:stun.l.google.com:19302' },
    { urls: 'stun:stun1.l.google.com:19302' }
];

let localStream = null;
let peerConnections = {};
let chatSocket = null;
let isJoined = false;
let isMuted = false;
let isVideoOff = false;

// 사용자 정보
let currentUser = {
    userId: Math.floor(Math.random() * 10000).toString(),
    userName: "사용자" + Math.floor(Math.random() * 100),
    channelName: "webrtc-room-" + (new URLSearchParams(window.location.search).get('project_id') || 'default')
};

scwin.onpageload = function() {
    console.log("������ webRTC 화상통화 페이지 초기화");

    // HTTPS 체크
    if (location.protocol !== 'https:' && location.hostname !== 'localhost') {
        alert("⚠️ webRTC는 HTTPS 환경에서만 작동합니다.");
        return;
    }

    // 데이터 초기화
    dma_videoChat.set("channelName", currentUser.channelName);
    dma_videoChat.set("userId", currentUser.userId);
    dma_videoChat.set("userName", currentUser.userName);
    dma_videoChat.set("isJoined", "false");

    // WebSocket 초기화
    scwin.initializeChatWebSocket();

    console.log("✅ webRTC 화상통화 시스템 준비 완료");
    scwin.addChatMessage("시스템", "✅ webRTC 화상통화방에 오신 것을 환영합니다!", false);
    scwin.addChatMessage("시스템", "������ '참가하기' 버튼을 눌러 화상통화를 시작하세요.", false);

    // ������ 엔터키 이벤트 리스너 추가
    setTimeout(() => {
        const chatInput = document.getElementById("chatInput");
        if (chatInput) {
            // ������ 엔터키 이벤트만 처리 (keydown 방식)
            chatInput.addEventListener('keydown', function(event) {
                if (event.keyCode === 13 || event.key === 'Enter') {
                    event.preventDefault();
                    scwin.sendChatMessage();
                    return false;
                }
            });

            chatInput.focus();
            console.log("✅ 엔터키 이벤트 연결 완료");
            scwin.addChatMessage("시스템", "������ 엔터키로 메시지 전송이 가능합니다.", false);
        } else {
            console.warn("⚠️ chatInput 요소를 찾을 수 없습니다");
        }
    }, 2000); // 충분한 로딩 시간 확보
};

// ������ 화상통화 참가
scwin.joinCall = async function() {
    try {
        scwin.showLoading("카메라와 마이크에 접근하는 중...");

        // 로컬 미디어 스트림 가져오기
        localStream = await navigator.mediaDevices.getUserMedia({
            video: { width: 1280, height: 720 },
            audio: true
        });

        // 로컬 비디오 표시
        const localVideo = document.getElementById("localVideo");
        if (localVideo) {
            localVideo.srcObject = localStream;
        }

        isJoined = true;
        dma_videoChat.set("isJoined", "true");

        // ������ WebSocket으로 화상통화방 참가 알림
        if (chatSocket && chatSocket.readyState === WebSocket.OPEN) {
            const joinRoomMessage = {
                type: 'join-room',
                channelName: currentUser.channelName,
                userId: currentUser.userId,
                userName: currentUser.userName,
                timestamp: Date.now()
            };
            chatSocket.send(JSON.stringify(joinRoomMessage));
            console.log("������ 화상통화방 참가 알림 전송:", joinRoomMessage);
        } else {
            console.error("❌ WebSocket 연결 안됨 - 화상통화 참가 실패");
        }

        scwin.updateControlButtons();
        scwin.hideLoading();

        scwin.addChatMessage("시스템", "✅ 화상통화에 참가했습니다!", false);
        console.log("✅ webRTC 화상통화 참가 완료");

    } catch (error) {
        console.error("❌ 화상통화 참가 실패:", error);
        scwin.hideLoading();

        let errorMessage = "카메라/마이크 접근 권한이 필요합니다";
        if (error.name === 'NotAllowedError') {
            errorMessage = "카메라/마이크 권한을 허용해주세요.";
        }

        alert("❌ " + errorMessage);
        scwin.addChatMessage("시스템", "❌ " + errorMessage, false);
    }
};

// ������ Peer Connection 생성
scwin.createPeerConnection = function(remoteUserId) {
    const peerConnection = new RTCPeerConnection({ iceServers: ICE_SERVERS });

    // 로컬 스트림을 Peer Connection에 추가
    if (localStream) {
        localStream.getTracks().forEach(track => {
            peerConnection.addTrack(track, localStream);
        });
    }

    // ICE Candidate 이벤트
    peerConnection.onicecandidate = (event) => {
        if (event.candidate && chatSocket && chatSocket.readyState === WebSocket.OPEN) {
            const candidateMessage = {
                type: 'ice-candidate',
                channelName: currentUser.channelName,
                userId: currentUser.userId,
                targetUserId: remoteUserId,
                iceCandidate: JSON.stringify(event.candidate)
            };
            chatSocket.send(JSON.stringify(candidateMessage));
        }
    };

    // 원격 스트림 수신
    peerConnection.ontrack = (event) => {
        console.log("������ 원격 스트림 수신:", remoteUserId);
        scwin.displayRemoteVideo(remoteUserId, event.streams[0]);
    };

    return peerConnection;
};

// ������ 원격 비디오 표시
scwin.displayRemoteVideo = function(userId, stream) {
    scwin.removeRemoteUser(userId);

    const container = document.createElement("div");
    container.className = "remote-user-video";
    container.id = `remote-${userId}`;

    const wrapper = document.createElement("div");
    wrapper.className = "remote-video-wrapper";

    const player = document.createElement("div");
    player.className = "remote-video-player";

    const video = document.createElement("video");
    video.autoplay = true;
    video.playsInline = true;
    video.srcObject = stream;

    const userName = document.createElement("div");
    userName.className = "remote-user-name";
    userName.textContent = `사용자${userId}`;

    player.appendChild(video);
    wrapper.appendChild(player);
    wrapper.appendChild(userName);
    container.appendChild(wrapper);

    document.getElementById("remoteVideosGrid").appendChild(container);
};

// ������ 화상통화 종료
scwin.leaveCall = async function() {
    try {
        // WebSocket으로 나가기 알림
        if (chatSocket && chatSocket.readyState === WebSocket.OPEN) {
            const leaveMessage = {
                type: 'leave-room',
                channelName: currentUser.channelName,
                userId: currentUser.userId,
                userName: currentUser.userName
            };
            chatSocket.send(JSON.stringify(leaveMessage));
        }

        // 모든 연결 정리
        Object.keys(peerConnections).forEach(userId => {
            if (peerConnections[userId]) {
                peerConnections[userId].close();
                delete peerConnections[userId];
            }
            scwin.removeRemoteUser(userId);
        });

        // 로컬 스트림 정리
        if (localStream) {
            localStream.getTracks().forEach(track => track.stop());
            localStream = null;
        }

        const localVideo = document.getElementById("localVideo");
        if (localVideo) localVideo.srcObject = null;

        isJoined = false;
        dma_videoChat.set("isJoined", "false");
        scwin.updateControlButtons();

        scwin.addChatMessage("시스템", "✅ 화상통화를 종료했습니다.", false);

    } catch (error) {
        console.error("화상통화 종료 실패:", error);
    }
};

// ������ 마이크 토글
scwin.toggleMute = function() {
    if (!localStream) return;

    const audioTracks = localStream.getAudioTracks();
    if (audioTracks.length > 0) {
        audioTracks[0].enabled = !audioTracks[0].enabled;
        isMuted = !audioTracks[0].enabled;
        dma_videoChat.set("isMuted", isMuted.toString());
        scwin.updateControlButtons();
    }
};

// ������ 비디오 토글
scwin.toggleVideo = function() {
    if (!localStream) return;

    const videoTracks = localStream.getVideoTracks();
    if (videoTracks.length > 0) {
        videoTracks[0].enabled = !videoTracks[0].enabled;
        isVideoOff = !videoTracks[0].enabled;
        dma_videoChat.set("isVideoOff", isVideoOff.toString());
        scwin.updateControlButtons();
    }
};

// ������️ 원격 사용자 제거
scwin.removeRemoteUser = function(userId) {
    const element = document.getElementById(`remote-${userId}`);
    if (element) element.remove();

    if (peerConnections[userId]) {
        peerConnections[userId].close();
        delete peerConnections[userId];
    }
};

// ������️ 버튼 상태 업데이트
scwin.updateControlButtons = function() {
    const joinBtn = document.getElementById("joinBtn");
    const leaveBtn = document.getElementById("leaveBtn");
    const muteBtn = document.getElementById("muteBtn");
    const videoBtn = document.getElementById("videoBtn");

    if (isJoined) {
        if (joinBtn) joinBtn.style.display = "none";
        if (leaveBtn) leaveBtn.style.display = "inline-block";
        if (muteBtn) {
            muteBtn.disabled = false;
            muteBtn.textContent = isMuted ? "MUTE" : "MIC";
            muteBtn.className = isMuted ? "control-btn mute-btn muted" : "control-btn mute-btn";
        }
        if (videoBtn) {
            videoBtn.disabled = false;
            videoBtn.textContent = isVideoOff ? "CAM OFF" : "CAM ON";
            videoBtn.className = isVideoOff ? "control-btn video-btn video-off" : "control-btn video-btn";
        }
    } else {
        if (joinBtn) joinBtn.style.display = "inline-block";
        if (leaveBtn) leaveBtn.style.display = "none";
        if (muteBtn) muteBtn.disabled = true;
        if (videoBtn) videoBtn.disabled = true;
    }
};

// ������ WebSocket 채팅 시스템
scwin.initializeChatWebSocket = function() {
    const protocol = window.location.protocol === 'https:' ? 'wss:' : 'ws:';
    const host = window.location.hostname;
    const port = window.location.port || (protocol === 'wss:' ? '443' : '80');

    // 여러 WebSocket URL 시도
    const wsUrls = [
        `${protocol}//${host}:${port}/InsWebApp/chat`,
        `ws://localhost:9093/InsWebApp/chat`,
        `wss://localhost:19443/InsWebApp/chat`
    ];

          let wsUrl = wsUrls[0];
      console.log("������ WebSocket 연결 시도:", wsUrl);

    try {
        chatSocket = new WebSocket(wsUrl);

        chatSocket.onopen = function() {
            console.log("✅ WebSocket 연결 성공");

            // 채널 참가
            const joinMessage = {
                type: 'join',
                channelName: currentUser.channelName,
                userId: currentUser.userId,
                userName: currentUser.userName
            };
            chatSocket.send(JSON.stringify(joinMessage));

            // ������ 채팅 히스토리 요청
            setTimeout(() => {
                const historyMessage = {
                    type: 'history',
                    channelName: currentUser.channelName,
                    afterTimestamp: 0
                };
                chatSocket.send(JSON.stringify(historyMessage));
                console.log("������ 채팅 히스토리 요청 전송");
            }, 1000);
        };

        chatSocket.onmessage = function(event) {
            try {
                const data = JSON.parse(event.data);
                console.log("������ WebSocket 메시지 수신:", data.type, data);

                switch(data.type) {
                case 'message':
                    // ������ 중복 방지: 내가 보낸 메시지는 무시 (이미 화면에 표시됨)
                    if (data.userId !== currentUser.userId) {
                        scwin.addChatMessage(data.userName, data.message, false, data.messageId);
                        console.log("������ 다른 사용자 메시지:", data.userName, "->", data.message);
                    } else {
                        // 내 메시지 서버 확인만 로깅
                        console.log("������ 내 메시지 서버 에코 무시:", data.message);
                    }
                    break;

                case 'history':
                    // ������ Redis 채팅 히스토리 처리
                    if (data.messages && data.messages.length > 0) {
                        console.log("������ 채팅 히스토리 로드:", data.messages.length, "개");

                        // 기존 메시지 클리어 (시스템 메시지 제외)
                        dlt_chatMessages.removeAll();
                        addedMessageIds.clear(); // ID 추적도 초기화

                        data.messages.forEach(msg => {
                            const isOwn = msg.userId === currentUser.userId;
                            const msgId = msg.messageId || `history_${msg.userId}_${msg.timestamp}`;
                            scwin.addChatMessage(msg.userName, msg.message, isOwn, msgId);
                        });

                        scwin.addChatMessage("시스템", `������ 이전 채팅 ${data.messages.length}개를 불러왔습니다.`, false);
                    } else {
                        console.log("������ 채팅 히스토리 없음");
                    }
                    break;

                case 'existing-users':
                    // ������ 기존 사용자들과 webRTC 연결 시작 (화상통화 참가 상태에서만)
                    console.log("기존 사용자들:", data.users, "내 화상통화 상태:", isJoined);
                    if (isJoined && localStream) {
                        data.users.forEach(userId => {
                            if (userId !== currentUser.userId) {
                                console.log("기존 사용자와 연결 시작:", userId);
                                scwin.createOffer(userId);
                            }
                        });
                    }
                    break;

                case 'user-joined':
                    scwin.addChatMessage("시스템", `${data.userName}님이 참가했습니다.`, false);
                    // ������ 새로운 사용자와 webRTC 연결 (내가 화상통화 중일 때만)
                    if (isJoined && localStream && data.userId !== currentUser.userId) {
                        console.log("������ 새 사용자 참가 - 연결 시작:", data.userId);
                        // 내가 먼저 Offer를 보내서 연결 시작
                        setTimeout(() => {
                            scwin.createOffer(data.userId);
                        }, 1000); // 1초 후 연결 시도 (상대방이 준비될 시간)
                    }
                    break;

                case 'user-left':
                    scwin.addChatMessage("시스템", `${data.userName}님이 나갔습니다.`, false);
                    scwin.removeRemoteUser(data.userId);
                    break;

                case 'offer':
                    // ������ webRTC Offer 수신 (화상통화 중일 때만 처리)
                    if (isJoined && localStream) {
                        console.log("Offer 수신:", data.userId);
                        scwin.handleOffer(data.userId, JSON.parse(data.sdp));
                    } else {
                        console.log("화상통화 미참가 상태로 Offer 무시:", data.userId);
                    }
                    break;

                case 'answer':
                    // ������ webRTC Answer 수신
                    if (isJoined && localStream) {
                        console.log("Answer 수신:", data.userId);
                        scwin.handleAnswer(data.userId, JSON.parse(data.sdp));
                    }
                    break;

                case 'ice-candidate':
                    // ������ ICE Candidate 수신
                    if (isJoined && localStream) {
                        console.log("ICE Candidate 수신:", data.userId);
                        scwin.handleIceCandidate(data.userId, JSON.parse(data.iceCandidate));
                    }
                    break;

                case 'notification':
                    scwin.addChatMessage("시스템", data.message, false);
                    break;

                default:
                    console.warn("알 수 없는 메시지 타입:", data.type, data);
                    break;
            }
            } catch (error) {
                console.error("❌ 메시지 처리 오류:", error);
                scwin.addChatMessage("시스템", "❌ 메시지 처리 중 오류 발생", false);
            }
        };

        chatSocket.onclose = function(event) {
            console.log("❌ WebSocket 연결 종료:", event.code, event.reason);

            // 정상 종료가 아닌 경우에만 재연결 시도
            if (event.code !== 1000) {
                scwin.addChatMessage("시스템", "⚠️ 서버와의 연결이 끊어졌습니다. 재연결 시도 중...", false);

                // 5초 후 재연결 (한 번만)
                setTimeout(() => {
                    console.log("������ WebSocket 재연결 시도...");
                    scwin.initializeChatWebSocket();
                }, 5000);
            }
        };

        chatSocket.onerror = function(error) {
            console.error("❌ WebSocket 오류:", error);
            scwin.addChatMessage("시스템", "❌ 서버 연결 오류 발생", false);
        };

    } catch (error) {
        console.error("❌ WebSocket 초기화 실패:", error);
        scwin.addChatMessage("시스템", "❌ WebSocket 초기화 실패", false);
    }
};

// ������ Offer 생성 (상세 로깅)
scwin.createOffer = async function(targetUserId) {
    try {
        console.log("������ Offer 생성 시작:", targetUserId);

        // Peer Connection 생성
        const peerConnection = scwin.createPeerConnection(targetUserId);
        peerConnections[targetUserId] = peerConnection;
        console.log("✅ PeerConnection 생성 완료:", targetUserId);

        // Offer 생성
        const offer = await peerConnection.createOffer();
        await peerConnection.setLocalDescription(offer);
        console.log("✅ Local Description 설정 완료:", targetUserId);

        // 서버로 Offer 전송
        const offerMessage = {
            type: 'offer',
            channelName: currentUser.channelName,
            userId: currentUser.userId,
            targetUserId: targetUserId,
            sdp: JSON.stringify(offer)
        };

        if (chatSocket && chatSocket.readyState === WebSocket.OPEN) {
            chatSocket.send(JSON.stringify(offerMessage));
            console.log("������ Offer 전송 완료:", targetUserId);
        } else {
            console.error("❌ WebSocket 연결 안됨 - Offer 전송 실패");
        }

    } catch (error) {
        console.error("❌ Offer 생성 실패:", targetUserId, error);
    }
};

// ������ Offer 처리 (Answer 생성)
scwin.handleOffer = async function(fromUserId, offer) {
    try {
        console.log("������ Offer 수신 처리 시작:", fromUserId);

        // Peer Connection 생성
        const peerConnection = scwin.createPeerConnection(fromUserId);
        peerConnections[fromUserId] = peerConnection;
        console.log("✅ PeerConnection 생성 완료:", fromUserId);

        // Remote Description 설정
        await peerConnection.setRemoteDescription(offer);
        console.log("✅ Remote Description 설정 완료:", fromUserId);

        // Answer 생성
        const answer = await peerConnection.createAnswer();
        await peerConnection.setLocalDescription(answer);
        console.log("✅ Answer 생성 완료:", fromUserId);

        // 서버로 Answer 전송
        const answerMessage = {
            type: 'answer',
            channelName: currentUser.channelName,
            userId: currentUser.userId,
            targetUserId: fromUserId,
            sdp: JSON.stringify(answer)
        };

        if (chatSocket && chatSocket.readyState === WebSocket.OPEN) {
            chatSocket.send(JSON.stringify(answerMessage));
            console.log("������ Answer 전송 완료:", fromUserId);
        } else {
            console.error("❌ WebSocket 연결 안됨 - Answer 전송 실패");
        }

    } catch (error) {
        console.error("❌ Answer 생성 실패:", fromUserId, error);
    }
};

// ������ Answer 처리
scwin.handleAnswer = async function(fromUserId, answer) {
    try {
        console.log("������ Answer 수신 처리:", fromUserId);
        const peerConnection = peerConnections[fromUserId];
        if (peerConnection) {
            await peerConnection.setRemoteDescription(answer);
            console.log("✅ Answer 처리 완료:", fromUserId);
        } else {
            console.error("❌ PeerConnection 없음:", fromUserId);
        }
    } catch (error) {
        console.error("❌ Answer 처리 실패:", fromUserId, error);
    }
};

// ������ ICE Candidate 처리
scwin.handleIceCandidate = async function(fromUserId, candidate) {
    try {
        console.log("������ ICE Candidate 수신:", fromUserId);
        const peerConnection = peerConnections[fromUserId];
        if (peerConnection) {
            await peerConnection.addIceCandidate(candidate);
            console.log("✅ ICE Candidate 추가 완료:", fromUserId);
        } else {
            console.error("❌ PeerConnection 없음:", fromUserId);
        }
    } catch (error) {
        console.error("❌ ICE Candidate 처리 실패:", fromUserId, error);
    }
};

// ������ 채팅 메시지 전송 (중복 방지)
let lastSentMessageTime = 0;
scwin.sendChatMessage = function() {
    const input = document.getElementById("chatInput");
    const message = input.value.trim();

    if (!message || !chatSocket || chatSocket.readyState !== WebSocket.OPEN) return;

    const now = Date.now();
    const messageData = {
        type: 'message',
        channelName: currentUser.channelName,
        userId: currentUser.userId,
        userName: currentUser.userName,
        message: message,
        timestamp: now,
        messageId: `${currentUser.userId}_${now}` // 고유 ID 생성
    };

    // ������ 즉시 내 메시지를 화면에 표시
    scwin.addChatMessage(currentUser.userName, message, true, messageData.messageId);
    lastSentMessageTime = now;

    chatSocket.send(JSON.stringify(messageData));
    input.value = "";
    input.focus();

    console.log("������ 메시지 전송:", messageData);
};

// ������ 채팅 메시지 추가 (중복 방지)
let addedMessageIds = new Set();
scwin.addChatMessage = function(userName, message, isOwn, messageId) {
    const timestamp = new Date().toLocaleTimeString();
    const msgId = messageId || `${isOwn ? currentUser.userId : 'other'}_${Date.now()}`;

    // 중복 메시지 방지
    if (addedMessageIds.has(msgId)) {
        console.log("������ 중복 메시지 방지:", msgId);
        return;
    }
    addedMessageIds.add(msgId);

    const rowIndex = dlt_chatMessages.insertRow();
    dlt_chatMessages.setCellData(rowIndex, "messageId", msgId);
    dlt_chatMessages.setCellData(rowIndex, "userId", isOwn ? currentUser.userId : "other");
    dlt_chatMessages.setCellData(rowIndex, "userName", userName);
    dlt_chatMessages.setCellData(rowIndex, "message", message);
    dlt_chatMessages.setCellData(rowIndex, "timestamp", timestamp);
    dlt_chatMessages.setCellData(rowIndex, "isOwn", isOwn.toString());

    scwin.updateChatMessages();
    console.log("✅ 메시지 추가:", userName, "->", message);
};

// ������ 채팅 UI 업데이트 (개선된 버전)
scwin.updateChatMessages = function() {
    const container = document.getElementById("chatMessages");
    if (!container) return;

    const messages = dlt_chatMessages.getAllJSON();
    container.innerHTML = "";

    messages.forEach(msg => {
        const div = document.createElement("div");
        div.className = `chat-message ${msg.isOwn === 'true' ? 'own' : 'other'}`;

        const header = document.createElement("div");
        header.style.fontSize = "11px";
        header.style.marginBottom = "2px";
        header.style.opacity = "0.7";
        header.style.fontWeight = "bold";
        header.textContent = `${msg.userName} ${msg.timestamp}`;

        const content = document.createElement("div");
        content.style.fontSize = "14px";
        content.style.lineHeight = "1.4";
        content.textContent = msg.message;

        div.appendChild(header);
        div.appendChild(content);
        container.appendChild(div);
    });

    // 스크롤을 맨 아래로
    setTimeout(() => {
        container.scrollTop = container.scrollHeight;
    }, 100);
};

// Enter 키 처리
scwin.handleChatKeyPress = function(event) {
    if (event.keyCode === 13) {
        scwin.sendChatMessage();
    }
};

// 유틸리티 함수들
scwin.showLoading = function(message) {
    console.log("로딩:", message);
};

scwin.hideLoading = function() {
    console.log("로딩 완료");
};

// 페이지 종료 시 정리
window.addEventListener("beforeunload", function() {
    if (isJoined) {
        scwin.leaveCall();
    }
    if (chatSocket) {
        chatSocket.close();
    }
});
